import { describe, expect, it } from "vitest";
import {
  applyCrossPromo,
  mapV2Status,
  getRevenueCatEventId,
  getRevenueCatUserCandidates,
  isAppId,
  isLocalOrigin,
  isProductionLike,
  mapAllEntitlements,
  normalizeOrigin,
  parseRuntimeEnv,
  validateRuntimeEnv,
  verifyRevenueCatAuthorization,
  type RuntimeEnv
} from "./index";

const validEnv = {
  APP_ENV: "local",
  APP_ORIGIN: "http://localhost:3001",
  SUPABASE_URL: "http://127.0.0.1:54321",
  SUPABASE_PUBLISHABLE_KEY: "publishable",
  SUPABASE_SECRET_KEY: "secret",
  REVENUECAT_WEBHOOK_AUTHORIZATION: "Bearer secret"
};

describe("product helpers", () => {
  it("should normalize origins", () => {
    expect(normalizeOrigin("https://example.com/path?x=1#hash")).toBe("https://example.com");
    expect(() => normalizeOrigin("ftp://example.com")).toThrow("Unsupported origin protocol");
  });
});

describe("isProductionLike", () => {
  it("should return true for production and staging only", () => {
    expect(isProductionLike("production")).toBe(true);
    expect(isProductionLike("staging")).toBe(true);
    expect(isProductionLike("local")).toBe(false);
    expect(isProductionLike("development")).toBe(false);
  });
});

describe("runtime env", () => {
  it("should parse local defaults and validate production safeguards", () => {
    const env = parseRuntimeEnv(validEnv);
    expect(isLocalOrigin(env.appOrigin)).toBe(true);

    const production: RuntimeEnv = {
      ...env,
      appEnv: "production"
    };
    expect(validateRuntimeEnv(production)).toEqual([
      "production origins cannot use localhost",
      "CF_VERIFY_SECRET is required in production",
      "REDIS_URL is required in production",
      "STRIPE_SECRET_KEY is required in production"
    ]);
  });

  it("should parse STRIPE_AUTOMATIC_TAX truthy and falsy strings", () => {
    expect(parseRuntimeEnv({ ...validEnv, STRIPE_AUTOMATIC_TAX: "true" }).stripeAutomaticTax).toBe(true);
    expect(parseRuntimeEnv({ ...validEnv, STRIPE_AUTOMATIC_TAX: "1" }).stripeAutomaticTax).toBe(true);
    expect(parseRuntimeEnv({ ...validEnv, STRIPE_AUTOMATIC_TAX: "no" }).stripeAutomaticTax).toBe(false);
    expect(parseRuntimeEnv({ ...validEnv, STRIPE_AUTOMATIC_TAX: undefined }).stripeAutomaticTax).toBe(false);
  });

  it("should reject invalid and missing env values", () => {
    expect(() => parseRuntimeEnv({ ...validEnv, APP_ENV: "prod" })).toThrow("Unsupported value");
    expect(() => parseRuntimeEnv({ ...validEnv, APP_ORIGIN: "" })).toThrow("Missing required environment value");
    expect(() =>
      parseRuntimeEnv({
        ...validEnv,
        APP_ENV: "production",
        APP_ORIGIN: "http://localhost:3001"
      })
    ).toThrow("production origins cannot use localhost");
  });
});

describe("apps allow-list", () => {
  it("should accept known app ids and reject others", () => {
    expect(isAppId("save-my-cactus")).toBe(true);
    expect(isAppId("appA")).toBe(false);
    expect(isAppId("appZ")).toBe(false);
    expect(isAppId("")).toBe(false);
    expect(isAppId(undefined)).toBe(false);
    expect(isAppId(42)).toBe(false);
  });
});

describe("cross-promo policy", () => {
  it("should yield no virtuals for empty policy or empty real", () => {
    expect(applyCrossPromo({}, {})).toEqual({});
    expect(applyCrossPromo({ pro_appA: true }, {})).toEqual({});
    expect(applyCrossPromo({}, { pro_appA: ["bonus_appB"] })).toEqual({});
  });

  it("should grant virtuals for active real entitlements only", () => {
    const policy = { pro_appA: ["bonus_appB"], pro_appB: ["bonus_appA"] };
    expect(applyCrossPromo({ pro_appA: true, pro_appB: false }, policy)).toEqual({ bonus_appB: true });
    expect(applyCrossPromo({ pro_appA: true, pro_appB: true }, policy)).toEqual({ bonus_appB: true, bonus_appA: true });
  });

  it("should accumulate without duplicates across multiple sources", () => {
    const policy = { pro_appA: ["bonus_appB"], pro_appB: ["bonus_appB"] };
    expect(applyCrossPromo({ pro_appA: true, pro_appB: true }, policy)).toEqual({ bonus_appB: true });
  });
});

describe("RevenueCat helpers", () => {
  it("should verify webhook auth, event ids, candidates, and hashes", () => {
    const payload = {
      api_version: "1.0",
      event: { id: " event_1 ", app_user_id: "user_a", original_app_user_id: "user_b", aliases: ["user_a", "user_c"] }
    };
    expect(verifyRevenueCatAuthorization("Bearer secret", "Bearer secret")).toBe(true);
    expect(verifyRevenueCatAuthorization("Bearer nope", "Bearer secret")).toBe(false);
    expect(verifyRevenueCatAuthorization("Bearer secret", "")).toBe(false);
    expect(getRevenueCatEventId(payload)).toBe("event_1");
    expect(getRevenueCatEventId({ event: {} })).toBeNull();
    expect(getRevenueCatUserCandidates(payload)).toEqual(["user_a", "user_b", "user_c"]);
    expect(getRevenueCatUserCandidates({ event: { aliases: [""] } })).toEqual([]);
  });

